mapper.select:
SELECT
  *
FROM sys_template
WHERE sys_template_group_id = #{query.sysTemplateGroupId}


  AND sys_template_name LIKE CONCAT('%',#{query.sysTemplateName},'%')



  AND sys_template_code LIKE CONCAT('%',#{query.sysTemplateCode},'%')



  AND sys_template_status = #{query.sysTemplateStatus}



  AND sys_template_type = #{query.sysTemplateType}



  AND sys_template_approve = #{query.sysTemplateApprove}



  AND sys_template_approve_reject LIKE CONCAT('%',#{query.sysTemplateApproveReject},'%')



  AND sys_template_approve_create_by = #{query.sysTemplateApproveCreateBy}



  AND sys_template_delete = 0
